// OMNA COLOR – the 180 exercises in English (20 October 2026, wish: «auch alle downloadbaren Apps … doppelsprachig deutsch/englisch»).
// The German originals stay in index.html (const EX); this file carries, per exercise number, the name (n), the steps (a), the material (m) and
// the closing question (f). Theme names and durations come from the original. Loaded as a plain script before the page's own one; the card reads it
// when the language is English (sprache.js).
window.EX_EN = {
  "001": { n: "Collect ten colours", a: ["Look around you for ten different colours.", "Lay the objects or pieces of paper side by side.", "Arrange them so that similar colours lie together."], m: "10 small coloured objects or pieces of paper", f: "Which colour was the hardest to find?" },
  "002": { n: "Almost the same colours", a: ["Look for five similar shades, for example five different greens.", "Lay them in a row from the lightest to the darkest shade.", "Compare each two neighbouring pieces."], m: "5 pieces of paper in similar shades", f: "Between which two shades do you see the smallest difference?" },
  "003": { n: "Find colour pairs", a: ["Look for these three colour pairs: red and green, blue and orange, yellow and violet.", "Cut a small piece of each colour.", "Lay the two colours of a pair directly side by side."], m: "Coloured paper or coloured packaging, scissors", f: "Which pair stands out most to you?" },
  "004": { n: "Warm and cool colours", a: ["Collect five pieces of colour that feel warm to you and five that feel cool.", "Form two groups from them.", "Take another piece of colour. Place it first with one group, then with the other."], m: "Coloured paper or coloured packaging, scissors", f: "Does the extra piece of colour look the same in both groups?" },
  "005": { n: "Colour in different light", a: ["Put the object by the window, in a shady corner and under a lamp.", "Look at it briefly in each place.", "Note each time whether its colour looks lighter, darker or different."], m: "A coloured object, paper, pen", f: "Where do you see the biggest difference?" },
  "006": { n: "Colours from packaging", a: ["Cut out ten small coloured pieces.", "Lay them side by side and look for things they have in common, such as similar brightness.", "Then sort them into groups without writing down colour names."], m: "Old magazines or packaging, scissors", f: "How do you recognise which pieces belong together?" },
  "007": { n: "Collect lines", a: ["Look around you for ten different lines, for example on a cable, a table edge or a leaf.", "Draw only the line from each find.", "Leave some space between the lines."], m: "Paper, pen", f: "Which line would you like to use in a drawing of your own?" },
  "008": { n: "Show movements with lines", a: ["Watch three movements, for example a hand, a door or a leaf in the wind.", "Draw each movement with two or three lines.", "Draw the path of the movement without depicting the whole object."], m: "Paper, pen", f: "In which drawing can you recognise the movement best?" },
  "009": { n: "Sort shapes", a: ["Look for ten shapes around you and draw their outlines quickly.", "Assign them to three groups: regular shapes like circle and rectangle; free shapes like the outline of a leaf; shapes that are hard to place.", "Compare the three groups."], m: "Paper, pen", f: "Which shape fits into more than one group for you?" },
  "010": { n: "Draw only the outline", a: ["Choose five things around you.", "Draw only the outer outline of each. Leave out everything inside.", "Look at the drawings without naming the things."], m: "Paper, pen", f: "Which shape could also belong to a completely different object?" },
  "011": { n: "Rub four surfaces", a: ["Look for four different surfaces, such as wood, a coin, cardboard and a leaf with veins.", "Lay paper on each and rub over it with the pencil lead held flat.", "Lay the four patterns side by side."], m: "Thin paper, soft pencil, 4 firm surfaces", f: "In which pattern can you recognise the surface particularly well?" },
  "012": { n: "Order materials by touch", a: ["Feel the five materials one after another with your fingers.", "Order them from as smooth as possible to as rough as possible.", "Then look at their surfaces."], m: "5 pieces of material, such as fabric, sponge, cardboard, wood and metal", f: "Do appearance and feel go together for you?" },
  "013": { n: "Change paper in five ways", a: ["Leave the first piece flat.", "Fold the second, tear the edge of the third, roll the fourth and crumple the fifth.", "Lay all five pieces side by side."], m: "5 equally sized pieces of the same paper", f: "With which piece has the effect of the paper changed the most?" },
  "014": { n: "Draw edges", a: ["Look for five different edges, such as on a book, fabric, a leaf, torn paper and two overlapping things.", "Draw each edge as a single line.", "Keep looking back at the edge as you draw."], m: "Paper, pen", f: "Which of the lines differs most from the others?" },
  "015": { n: "Draw the spaces between", a: ["Lay the objects on the table with some distance between them.", "Look for five gaps between them.", "Draw only the shapes of these gaps."], m: "Paper, pen, a few small objects", f: "Which gap looks like a shape of its own on the paper?" },
  "016": { n: "Find similar shapes", a: ["Choose a shape from your surroundings, for example a circle.", "Look for six places where this shape occurs.", "Draw the six finds small, side by side."], m: "Paper, pen", f: "What do the shapes have in common, even though they look different?" },
  "017": { n: "Almost mirror images", a: ["Look for three things whose left and right halves resemble each other, such as a leaf or a window.", "Draw them roughly.", "Mark one place on each where the two halves differ."], m: "Paper, pen", f: "Which deviation stands out most to you?" },
  "018": { n: "Draw stains and cracks", a: ["Look for five traces that came about by chance, such as stains, cracks or worn spots.", "Draw each trace as a shape on its own sheet.", "Lay the five drawings side by side in a way you like."], m: "5 small sheets, pen", f: "Which trace would suit you best as a starting point for a picture?" },
  "019": { n: "Draw shadows", a: ["Light an object from the side so that its shadow falls on the paper.", "Trace the outline of the shadow.", "Repeat with other objects or positions of the light until you have five outlines."], m: "Paper, pen, small objects, desk lamp", f: "In which shadow can you barely recognise the object any more?" },
  "020": { n: "Seeing through and reflections", a: ["Look for five places where you see something through a surface or as a reflection.", "Look through a window, into a mirror or at a shiny spoon, for example.", "Sketch briefly what you see in each case."], m: "Paper, pen, glass surfaces or reflective things around you", f: "Where do you see the surface and something behind or inside it at the same time?" },
  "021": { n: "Find connections", a: ["Look for five connections, such as a knot, a button, a zip, a strip of tape and a door hinge.", "Draw only the spot where the parts are held together.", "Write briefly next to each how it holds."], m: "Paper, pen", f: "Which connection could you try with your own material?" },
  "022": { n: "Three crops of a view", a: ["Form a small rectangular frame with your thumbs and index fingers.", "Look through it at the view.", "Find three different crops by moving the frame or changing its size."], m: "A view in the room or out of the window, your hands", f: "What do you notice first in each crop?" },
  "023": { n: "Look from five distances", a: ["Look at the object very close up, from an arm's length and from one, two and three steps away.", "At each position note three things you see.", "Compare your notes."], m: "An object, paper, pen", f: "Which detail can no longer be seen from the greatest distance?" },
  "024": { n: "Draw from five sides", a: ["Look at the object from above, below, front, back and at an angle. Turn it in your hand to do so.", "From each direction draw only its outline for 30 seconds.", "Lay the five views side by side."], m: "A small object, paper, pen, timer", f: "From which direction is the object easiest to recognise?" },
  "025": { n: "From light to dark", a: ["Look for five pieces of paper: a very light one, a very dark one and three in between.", "Lay them in a row from the lightest to the darkest piece.", "Compare the brightness of neighbouring pieces."], m: "5 pieces of paper of different brightness", f: "Where is the difference in brightness particularly large?" },
  "026": { n: "Sounds as lines", a: ["Listen to the sounds around you for two minutes.", "For five sounds draw one line each, perhaps short, shaky, wavy or broken.", "Leave out the sources of the sounds; so do not draw a bird, for instance."], m: "Paper, pen, timer", f: "Which of your lines fits the sound you heard best, for you?" },
  "027": { n: "Feel, then draw from memory", a: ["Close your eyes and feel an object with both hands.", "Put it out of sight. Open your eyes and draw its shape and surface from memory.", "Repeat with the other two objects. Then compare the drawings and the things."], m: "3 small objects without sharp edges, paper, pen", f: "Which quality could you feel well but draw with difficulty?" },
  "028": { n: "Compare five papers", a: ["Bend each paper slightly and order the papers from soft to stiff.", "Feel the surfaces and order them from smooth to rough.", "Hold each paper up to the window and compare how much light comes through."], m: "5 different papers, such as newspaper, copy paper, cardboard, baking paper and gift wrap", f: "Which paper would you choose for folding, which for drawing?" },
  "029": { n: "Natural shapes and made shapes", a: ["Look for five shapes from nature and five on made things.", "Draw them small, for example a leaf and a spoon.", "Connect two drawings whose shapes resemble each other although they come from different groups."], m: "Paper, pen", f: "In what way are the two shapes alike?" },
  "030": { n: "Remember a colour", a: ["Look at the colour of the object for 20 seconds.", "Put the object out of sight. Choose the closest coloured pencil and paint a small patch of colour.", "Bring the object back and compare the colours."], m: "A coloured object, several coloured pencils, paper, timer", f: "Is your patch lighter, darker or similar to the original?" },
  "031": { n: "Draw a small detail large", a: ["Choose a small detail, such as a leaf vein, a corner or a crop of a picture.", "Draw this detail so large that it almost fills your sheet.", "Leave out everything outside the chosen detail."], m: "A picture or object, paper, pen", f: "In the large drawing, can you still tell where the detail comes from?" },
  "032": { n: "Draw with fewer shapes", a: ["First draw the subject with ten simple shapes.", "Draw this version again next to it with five shapes. Combine parts or leave them out.", "From that, draw a third version with only three shapes."], m: "A photo with several details, paper, pen", f: "Which shape had to be kept until the very end, for you?" },
  "033": { n: "Turn and add", a: ["Turn the drawing a quarter turn and add exactly one shape.", "Turn it another quarter turn and add one more shape.", "Repeat a third time."], m: "A drawing of your own, pen", f: "In which position was it easiest for you to add something?" },
  "034": { n: "Mirror a picture", a: ["Draw the original the other way round: what is on the left goes to the right.", "Compare the two versions.", "In the mirrored drawing change exactly one shape, for example its size."], m: "A simple drawing, paper, pen", f: "What do you notice anew because of this one change?" },
  "035": { n: "Choose three crops", a: ["Lay the paper strips as a frame on your work.", "Move the frame and look for three different crops.", "Photograph each crop so that only the framed area can be seen."], m: "A work of your own, 4 paper strips, smartphone", f: "Which crop looks like a picture of its own to you?" },
  "036": { n: "Design the space around a shape", a: ["Draw a simple closed shape in the middle of the sheet.", "Leave its inside white and design only the area around it.", "Fill this area with colours, lines or patterns."], m: "Paper, pencil, coloured pencils", f: "How does the white shape look because of its surroundings?" },
  "037": { n: "Try other colours", a: ["Draw the most important shapes of your original on a new sheet.", "Keep the shapes roughly the same size and in the same place.", "Colour each shape with a different colour than in the original."], m: "A coloured drawing of your own, paper, coloured pencils", f: "What looks different because of the new colours?" },
  "038": { n: "One colour on two backgrounds", a: ["Cut two equally sized squares from the same paper.", "Place one of the squares on each background.", "Push the backgrounds side by side and compare the squares."], m: "A piece of coloured paper, 2 sheets of different colours, scissors", f: "Do the two squares look the same or different to you?" },
  "039": { n: "Watch an afterimage", a: ["Lay both papers side by side.", "Look at the middle of the coloured paper for about 20 seconds. Blink as normal.", "Then look at the white paper and watch whether a colour appears there briefly."], m: "A piece of strongly coloured paper, white paper, timer", f: "What do you see on the white paper, if anything appears at all?" },
  "040": { n: "Connect two colours", a: ["Paint a patch with the first colour on the left and one with the second on the right.", "Paint seven more patches in between. For each, mix a little more of the second colour into the first.", "Look at the whole row of colours."], m: "2 watercolours, brush, water, mixing surface, paper", f: "Between which patches is the change of colour particularly clear?" },
  "041": { n: "Four pictures with four colours", a: ["Paint a few simple shapes on each sheet.", "Use the same four colours on every sheet.", "From sheet to sheet, change where the colours lie and how much space they get."], m: "4 small sheets, 4 coloured pencils", f: "Which of the four pictures feels calmest to you?" },
  "042": { n: "A picture from paper surfaces", a: ["Look in the photo for the five largest or most striking areas of colour.", "Cut a roughly matching shape from coloured paper for each.", "Lay them on the base as in the photo and glue them down. Leave out small details."], m: "A photo, coloured paper, scissors, glue, a sheet as a base", f: "Which area helps you most to recognise the photo?" },
  "043": { n: "An object in three versions", a: ["Draw the object with the details you notice.", "Draw it again next to it and leave out small details.", "Draw a third version from no more than three simple shapes or lines."], m: "A small object, paper, pen", f: "In which version can you still recognise the object well?" },
  "044": { n: "A subject from five paper shapes", a: ["Choose a simple subject, for example a tree or a cup.", "Cut out no more than five shapes for it.", "Put them together into your subject and glue them down."], m: "Coloured paper, scissors, glue, a sheet as a base", f: "Which shape is particularly important for recognising it?" },
  "045": { n: "Colour in the areas between lines", a: ["Look in the drawing for areas completely enclosed by lines.", "Colour in these areas.", "Compare the coloured areas with places where there are only lines."], m: "A line drawing of your own, coloured pencils", f: "What stands out more after colouring in?" },
  "046": { n: "Build a line in space", a: ["Draw a simple curved line.", "Bend the pipe cleaner so that it resembles this line.", "Now bend some parts upwards while others stay on the table."], m: "Paper, pen, pipe cleaner", f: "How does the line change when you look at it from the side?" },
  "047": { n: "Form a space from one sheet", a: ["Fold the sheet and stand it up so that an opening appears underneath.", "Change the shape with further folds or cuts.", "Try to create several small openings or gaps with the same sheet."], m: "A sheet of paper, scissors", f: "Which fold keeps your shape open?" },
  "048": { n: "Make paper look like bark", a: ["Look at the grooves and cracks of the bark.", "Crumple, fold or tear your paper so that its surface becomes more like the bark.", "Lay the result next to the original."], m: "Paper, a piece of tree bark or a photo of it", f: "Which change makes the paper look most like bark?" },
  "049": { n: "Make light paper look heavy", a: ["Take a light piece of paper and look at it briefly.", "Fold, roll or crumple it so that it looks as solid and heavy as possible.", "Put it on the table and look at it from a little distance."], m: "Thin paper", f: "What makes the shape look heavy although the material is light?" },
  "050": { n: "Cut up and lay out anew", a: ["Cut the drawing into at least eight pieces.", "Put them together anew on the base. Turn and shift individual pieces.", "Choose an arrangement you want to leave as it is."], m: "A drawing of your own you can spare, scissors, a sheet as a base", f: "What of the original picture do you still recognise?" },
  "051": { n: "Let paper shapes fall", a: ["Let the shapes fall onto the base from a low height.", "Look at how they lie without moving anything at once.", "Then change the position of exactly three shapes."], m: "Small paper shapes, a sheet as a base", f: "Which of your three changes makes the biggest difference?" },
  "052": { n: "Continue a quick line", a: ["Without a sketch, draw a quick line across the sheet.", "Then look for two spots that interest you, such as a crossing or a loop.", "Add further lines or areas only at these two spots."], m: "Paper, pen", f: "What do you recognise there after drawing on?" },
  "053": { n: "Begin without looking", a: ["Draw the object for one minute without looking at the paper.", "Look at the result.", "Add exactly three lines or areas. Leave the rest as it is."], m: "A small object, paper, pen, timer", f: "Which unplanned spot do you want to leave unchanged?" },
  "054": { n: "Compare print and original", a: ["Paint a simple shape with one clearly longer side onto the plate.", "Press a sheet onto the still wet paint and peel it off carefully.", "Compare print and original. Add a new shape to the print."], m: "Small plastic plate without sharp edges, gouache, brush, paper", f: "What has changed in the print about the direction?" },
  "055": { n: "Reorder rubbed patterns", a: ["Lay paper on each surface and rub over it with the flat pencil lead.", "Cut a few shapes from the three patterns.", "Put them together on a new sheet. You do not have to depict an object with them."], m: "Paper, soft pencil, 3 firm surfaces, scissors", f: "Which pattern do you recognise even in its new shape?" },
  "056": { n: "Draw, glue and build a subject", a: ["Choose a simple subject, such as a tree.", "First draw it on paper.", "Then put it together from pieces of paper and finally build a small shape from modelling clay."], m: "Paper, pen, scissors, glue, small pieces of paper, modelling clay", f: "How do you recognise the subject in all three versions?" },
  "057": { n: "Lay two drawings over each other", a: ["Draw a simple pattern on each sheet, for example circles and stripes.", "Lay the sheets on top of each other.", "Shift and turn the upper sheet. Look for a position you like."], m: "2 sheets of tracing paper, pen", f: "Which shape only appears through the overlay?" },
  "058": { n: "Distort a picture with boxes", a: ["Draw a grid of three by three equally sized boxes. Draw a simple subject into it.", "Draw a second grid next to it whose middle column is twice as wide.", "Transfer the subject box by box into the new grid."], m: "Paper, pencil, ruler", f: "Which part of the subject changes the most?" },
  "059": { n: "A shape changes", a: ["Divide the sheet into three fields.", "Draw the same shape three times: before a change, during it and after it. Show, for example, a circle slowly opening.", "Leave out explanatory words."], m: "Paper, pen", f: "How do you recognise the order of the three pictures?" },
  "060": { n: "Begin with a leftover", a: ["Choose a leftover whose shape or colour interests you.", "Place it on a new sheet and glue it down.", "Add lines or shapes that connect to it."], m: "A paper leftover from an earlier work, paper, pen, glue", f: "Which quality of the leftover guided you as you worked on?" },
  "061": { n: "A picture with three colours", a: ["Choose three coloured pencils.", "Draw and colour a small picture of simple shapes with them.", "Keep the colours separate so that no further mixed colours appear. White paper may remain visible."], m: "Paper, 3 coloured pencils", f: "Which of the three colours do you notice first?" },
  "062": { n: "Repeat a shape many times", a: ["Choose a basic shape, for example a triangle.", "Draw it several times on the sheet: small and large, turned and partly overlapping.", "Use only this one kind of shape."], m: "Paper, pen", f: "Which change brings the most variety into the picture for you?" },
  "063": { n: "A picture from lines", a: ["On one part of the sheet draw lines densely side by side.", "In another place set a few lines with large gaps.", "Add lines in another direction until a picture appears for you."], m: "Paper, pen", f: "Where do the lines work together like a surface?" },
  "064": { n: "Regular or free shapes", a: ["Choose a rule: only circles, triangles and rectangles, or only freely drawn shapes with irregular edges.", "Fill part of the sheet with shapes from your chosen group.", "Keep the rule until the end."], m: "Paper, pen", f: "Which shape would you have liked to add that your rule does not allow?" },
  "065": { n: "Open or closed shapes", a: ["Decide on open outlines with a gap or on completely closed outlines.", "Draw a small picture with them.", "At the end check whether all shapes follow your rule."], m: "Paper, pen", f: "Which shape looks particularly open or particularly closed to you?" },
  "066": { n: "Mirror image with one deviation", a: ["Fold the sheet in the middle and open it again.", "Draw shapes as mirror-like as possible to the left and right of the fold line.", "On one side change exactly one small spot."], m: "Paper, pencil, coloured pencil", f: "How quickly do you find the changed spot when you look again?" },
  "067": { n: "Balance three shapes", a: ["Place the three shapes on the base, such as a large circle, a small triangle and a narrow strip.", "Shift them until no side feels too full or too empty to you.", "Avoid a mirror-symmetrical arrangement."], m: "3 different paper shapes, a sheet as a base", f: "Which shape did you have to move the most to achieve that?" },
  "068": { n: "Leave the middle free", a: ["Mark the middle of the sheet very lightly with a small dot.", "Draw a picture of shapes without touching the dot.", "Look at the picture from a little distance."], m: "Paper, pen", f: "Where do you look first, although the middle of the sheet is not there?" },
  "069": { n: "One shape should stand out", a: ["Draw a shape that should stand out first later on.", "Add further shapes. Choose their size, colour and position so that the first shape stays striking.", "Look away briefly and then at the sheet again."], m: "Paper, coloured pencils", f: "What determines which shape you notice first?" },
  "070": { n: "Which area becomes the shape", a: ["Draw an irregular line from the top to the bottom edge of the sheet.", "Paint the area to its left black. Leave the right area white.", "First look at the black side as the shape and the white as the background. Then try it the other way round."], m: "White paper, black felt pen", f: "Can you switch between the two ways of seeing?" },
  "071": { n: "Half stays empty", a: ["Imagine a line dividing the sheet into two equal halves.", "Design a picture only on one side of this line.", "Leave the other half completely empty."], m: "Paper, coloured pencils", f: "How does the empty half affect the picture?" },
  "072": { n: "From dense to loose", a: ["On the left of the sheet set many small dots densely side by side.", "Work on towards the right and gradually increase the gaps.", "At the right edge leave only a few single dots."], m: "Paper, pen", f: "Where do you still recognise single dots, where rather a surface?" },
  "073": { n: "Draw a recurring sequence", a: ["Choose a shape, for example a circle.", "Draw it in the sequence small, small, large. Repeat this group of three at least four times.", "Leave a little more space between the groups."], m: "Paper, pen", f: "Can you recognise the recurring groups at a glance?" },
  "074": { n: "Change a rule slowly", a: ["Draw six equally sized shapes with equal gaps in a row.", "Continue the row. Now change the gaps little by little.", "Let the last shapes be clearly more irregularly spaced."], m: "Paper, pen", f: "From which point do you notice the change?" },
  "075": { n: "A shape in three sizes", a: ["Choose a shape and draw it once small, once medium and once large.", "Fill part of the sheet with repetitions of these three templates.", "Use no other sizes."], m: "Paper, pen", f: "Which of the three sizes do you notice first in the finished picture?" },
  "076": { n: "Squares with fixed sizes", a: ["Draw squares with sides of 1, 2 and 4 centimetres and cut them out.", "Place the three squares on the base.", "Shift them until you like the distribution."], m: "Paper, ruler, pen, scissors, a sheet as a base", f: "Which distance between the squares feels right to you?" },
  "077": { n: "Only paper and string", a: ["Build a small shape from these two materials only.", "Fold or roll the paper and join it with the string, for example by wrapping and knotting.", "Leave both materials visible."], m: "Paper, string", f: "What does the string make possible that the paper alone could not?" },
  "078": { n: "Build without glue", a: ["Cut at least three parts from the cardboard.", "Join them by folding, clamping or slotting into each other.", "Build a small shape from them that stands by itself. Use no glue."], m: "Cardboard leftovers, scissors", f: "Which joint holds most reliably?" },
  "079": { n: "Hold parts together by weight", a: ["Build a small bridge or tower from the parts.", "Stack, lean or wedge the parts so that they hold together without glue or string.", "Move one part carefully and watch when the shape becomes more or less stable."], m: "Light building blocks and pieces of cardboard", f: "Which part holds something else in place by its weight?" },
  "080": { n: "Show an idea with paper", a: ["Choose an idea, for example «rising», «fanning out» or «getting denser».", "Fold, tear or roll pieces of paper so that you can show the idea with them.", "Arrange the pieces into a small composition."], m: "A few sheets of paper", f: "Where is your chosen idea easiest to recognise?" },
  "081": { n: "Exactly ten cuts", a: ["Cut the paper with exactly ten cuts. Each cut runs from one edge to another.", "Count the cuts and stop after the tenth.", "Put the resulting pieces together into a picture on the base."], m: "Paper, scissors, a sheet as a base", f: "Which piece determines your arrangement the most?" },
  "082": { n: "Only curved lines", a: ["Draw a picture in which every line is curved.", "Try tight and wide arcs as well as small and large curves.", "Connect some lines and let others stand alone."], m: "Paper, pen", f: "What makes your picture look ordered or disordered?" },
  "083": { n: "Only straight lines", a: ["Draw a picture only from straight lines.", "Let the lines run in different directions and meet in some places.", "Add narrow and wide angles."], m: "Paper, pen", f: "Where does movement seem to arise for you?" },
  "084": { n: "One line through the whole sheet", a: ["Put the pen down at one spot on the sheet.", "Lead a single line through different areas of the sheet. It may cross itself.", "Lift the pen only when you want to end the drawing."], m: "Paper, pen", f: "Where does your line create closed shapes?" },
  "085": { n: "Draw space with black and white", a: ["Draw several shapes that partly cover each other.", "Paint some black and leave others white.", "Use no grey hatching or further colours."], m: "White paper, black felt pen", f: "Which shape seems to lie in front, which behind?" },
  "086": { n: "A picture with five greys", a: ["Draw five small boxes at the edge.", "Leave the first white. Hatch the others progressively darker until the last is very dark.", "Draw simple shapes underneath and fill them with these five tones."], m: "Paper, soft pencil", f: "Which shapes stand out clearly from each other?" },
  "087": { n: "Two opposite colours", a: ["Paint a few red and green areas on the sheet.", "Let some areas border directly on each other and others be separated by white paper.", "Use only these two pencils."], m: "White paper, red and green coloured pencil", f: "Where do the two colours strike you most strongly?" },
  "088": { n: "Similar colours in the picture", a: ["Choose similar colours, for example light green, dark green and blue-green.", "Paint large and small areas with them, some in the middle and others at the edge.", "Look at the picture from a little distance."], m: "Paper, 3 to 5 coloured pencils in similar shades", f: "Which area seems nearer, which further away, if you see a difference?" },
  "089": { n: "Same colours in other amounts", a: ["On the first sheet paint four areas of colour: one large, two medium and one very small.", "On the second sheet paint the same colours in similar places.", "This time swap the sizes of the largest and the smallest area."], m: "2 sheets, 4 coloured pencils", f: "Which colour do you notice first on each sheet?" },
  "090": { n: "Stop by a fixed rule", a: ["Before you begin, decide that your drawing will consist of exactly 20 strokes.", "Draw and count each stroke.", "Put the pen down after the twentieth stroke."], m: "Paper, pen", f: "What would you still add if the rule allowed it?" },
  "091": { n: "Draw without looking at the sheet", a: ["Put the object in front of you and set the pen on the paper.", "Follow its outer edge slowly with your eyes. Move the pen along at the same time without lifting it.", "Look at the drawing only once you have gone all the way round the object."], m: "A small object, paper, pen", f: "Which part of the object do you recognise in your drawing?" },
  "092": { n: "Draw an outline slowly", a: ["Choose a starting point on the edge of the object.", "Trace the outline slowly. Let eyes and hand travel at the same speed as far as possible.", "Look alternately at the object and at the paper."], m: "A small object, paper, pen", f: "Where did you have to look particularly closely?" },
  "093": { n: "Draw in 30 seconds", a: ["Set the timer to 30 seconds.", "Draw only the most important directions and the rough shape of your model.", "Repeat four more times in free spots on the sheet."], m: "An object or a photo of a movement, paper, pen, timer", f: "Which lines reappear in several drawings?" },
  "094": { n: "Draw with the other hand", a: ["Draw the object with your usual writing hand.", "Draw it again next to it with the other hand.", "Compare the two drawings."], m: "A small object, paper, pen", f: "What differences do you see in the lines?" },
  "095": { n: "Five minutes without lifting the pen", a: ["Choose a simple subject, for example a plant.", "Set the timer to five minutes and draw without lifting the pen.", "If you want to continue somewhere else, connect the places with a line."], m: "Paper, pen, timer", f: "Which connections came about because of the rule?" },
  "096": { n: "Draw with the whole arm", a: ["Position the paper so that your arm has plenty of room.", "Draw large arcs and long lines by moving the whole arm from the shoulder.", "Try several directions."], m: "Large paper, soft pencil or chalk", f: "Which lines differ from your usual small hand movements?" },
  "097": { n: "Draw lightly and firmly", a: ["Draw ten lines of roughly equal length one below the other.", "Press only lightly for the first line. Increase the pressure a little with each further line.", "Keep the same grip on the pen as far as possible."], m: "Paper, pencil", f: "Between which lines is the difference clearest?" },
  "098": { n: "Five marks with one brush", a: ["Paint one mark with the tip of the brush and one with its broad side.", "Try one mark each with little and with plenty of water.", "Turn the brush while painting for a fifth mark."], m: "Paper, brush, watercolour, water", f: "Which mark would you like to use again?" },
  "099": { n: "Paint with other tools", a: ["Pick up some paint with the plastic card and drag it across the paper.", "Dab paint next to it with the sponge.", "Draw another mark with the wooden stick. Compare the three results."], m: "Paper, liquid poster paint, old plastic card, sponge, wooden stick", f: "Which mark could you predict the least?" },
  "100": { n: "A surface from fingerprints", a: ["With one finger set a few prints side by side.", "In a second place set many prints densely on top of each other.", "Compare the loose and the dense surface."], m: "Paper, finger paint, damp cloth", f: "Where do you still recognise single prints?" },
  "101": { n: "Scratch out light marks", a: ["Colour a small area firmly with the light crayon.", "Cover it with a layer of black crayon.", "Scratch lines through the black layer with the wooden stick so that the light colour shows."], m: "Paper, light and black oil pastel, wooden stick", f: "Which marks stand out particularly on the dark ground?" },
  "102": { n: "Let paint run", a: ["Put a drop of paint on the paper at the top edge.", "Lift this edge slightly so that the drop runs downwards.", "Turn the sheet at most three times to try new directions of flow. Do not trace the marks."], m: "Paper, liquid watercolour, brush, base", f: "Where did a turn change the path of the paint most?" },
  "103": { n: "A shape from dots", a: ["Choose a simple shape, for example a circle.", "Build it exclusively from dots.", "Set some dots close together and others far apart. Vary their size too."], m: "Paper, felt pen", f: "From which spacing do the dots look like a continuous surface to you?" },
  "104": { n: "Print with a foam plate", a: ["Press lines into the plate with the ballpoint pen without piercing it.", "Roll on a thin layer of ink. Lay paper on it, press it down and peel it off.", "Make a second print with a little more or less ink."], m: "Foam printing plate, ballpoint pen, water-based printing ink, roller, 2 sheets", f: "Which lines are clearer in which print?" },
  "105": { n: "Reassemble painted paper", a: ["Paint three pieces of paper differently, perhaps with blots, stripes and a single-colour area. Let them dry.", "Cut a few shapes from them.", "Lay the shapes on a new sheet and glue them into a picture."], m: "Paper, watercolours, brush, water, scissors, glue", f: "Which painted mark stands out particularly in the new picture?" },
  "106": { n: "Cut out shapes and shift them", a: ["Cut out a few shapes without drawing first.", "Lay them on the base and try three different arrangements.", "Choose one arrangement. You can leave it lying or glue it down."], m: "Coloured paper, scissors, a sheet as a base, glue if you wish", f: "Which shift changed the picture most?" },
  "107": { n: "Weave on cardboard", a: ["Cut six small slits into the cardboard at the top and six opposite at the bottom.", "Wind wool around the cardboard six times. Lay it in the slits and knot the ends at the back.", "Lead the second wool across, alternately over and under the stretched threads.", "Weave back in the next row and swap over and under."], m: "A postcard-sized piece of cardboard, wool in 2 colours, scissors", f: "Which pattern appears from the alternation of the two threads?" },
  "108": { n: "Lines of salt", a: ["Sprinkle a few lines of salt on the tray with the spoon.", "Push them together into a surface with the card.", "Draw new lines through the salt with the tip of the spoon."], m: "Dark tray, salt, spoon, old plastic card", f: "Which shape do you like enough to leave it standing for a while?" },
  "109": { n: "Make a sheet stand up", a: ["Fold over part of the sheet at the bottom as a base.", "Change the upper part with folds and cuts.", "Stand the sheet up and adjust the base until it stands by itself."], m: "A sheet of paper or thin cardboard, scissors", f: "Which change made your shape more stable?" },
  "110": { n: "Slot cardboard together", a: ["Cut out two rectangles. Cut a narrow slit into each from the edge to about the middle.", "Slot the two rectangles into each other at right angles.", "Add a third piece of cardboard with a matching slit."], m: "Thin cardboard, scissors", f: "How deep do the slits have to be for the parts to hold well?" },
  "111": { n: "Shape clay with six movements", a: ["Press a piece of clay flat, roll it and stretch it out.", "Fold it, pinch one spot together and press hollows into it with a fingertip.", "After each movement look briefly at the change."], m: "Modelling clay, base", f: "Which movement leaves the clearest trace?" },
  "112": { n: "Build a shape twice", a: ["Build a simple shape that stands by itself.", "Press it flat or pull it strongly apart.", "From this changed piece build a second shape that also stands."], m: "Modelling clay, base", f: "What in the second shape still recalls the first?" },
  "113": { n: "Join five found objects", a: ["Lay the found objects in front of you and try out which go together.", "Join them into a small shape, for example by wrapping, clamping or slotting.", "At least two joints should hold without glue."], m: "5 small found objects without sharp edges, string, clips", f: "Which joint suits the shape and material of the parts particularly well?" },
  "114": { n: "Rub a surface four times", a: ["Lay the first sheet on the surface and rub lightly over it with the flat pencil lead.", "Repeat on the other sheets with a little more, medium and firm pressure.", "Compare the four rubbings."], m: "4 sheets of thin paper, soft pencil, a firm textured surface", f: "At which pressure does the pattern become clearest?" },
  "115": { n: "Make a print", a: ["Spread a thin layer of paint on the plate.", "Draw lines through the still wet paint with the cotton bud.", "Lay paper on it, press it down with your hand and lift it off carefully."], m: "Smooth plastic plate without sharp edges, gouache, brush, cotton bud, paper", f: "Which marks on the paper are different from those on the plate?" },
  "116": { n: "Use a shape and its hole", a: ["Fold a sheet. Cut half a shape out at the fold and open both parts.", "Lay the cut-out shape on the base and paint around its edge.", "Next to it lay the paper with the hole and paint in the opening."], m: "Paper, scissors, wax crayon, a sheet as a base", f: "How do the two resulting shapes differ?" },
  "117": { n: "With a wet and an almost dry brush", a: ["Moisten a small area of the paper with water and set paint into it.", "Pick up the same paint with the brush and wipe off plenty of water on the cloth.", "Paint with the almost dry brush on a dry area of the sheet."], m: "Watercolour paper, watercolour, brush, water, cloth", f: "How do the edges and marks of the two areas differ?" },
  "118": { n: "Lay coloured layers over each other", a: ["Cut a simple shape from each sheet of film.", "Lay the shapes on white paper so that they partly overlap.", "Shift them and look at the places with two or three layers."], m: "3 transparent films of different colours, white paper, scissors", f: "Which colours do you see only where the films overlap?" },
  "119": { n: "Draw the same subject with more time", a: ["Draw the object on the first sheet for 30 seconds.", "Draw it on the second sheet for three minutes.", "Draw it on the third sheet for ten minutes. Always use the same pen."], m: "An object, 3 sheets, pen, timer", f: "What does the longest drawing show in addition, and what do you like about the shortest?" },
  "120": { n: "Twelve small variations", a: ["Choose a simple shape, such as a leaf.", "Draw twelve small variations of it. Compared with the starting shape change only one feature each time, such as size, direction or edge.", "Compare the twelve variations."], m: "Paper, pen", f: "Which small change makes the biggest difference?" },
  "121": { n: "Describe what can be seen", a: ["Look at your work for one minute.", "Write down five visible things, for example «three red dots» or «a line at the edge».", "Leave out judgements and assumed meanings for now."], m: "A work of your own, paper, pen, timer", f: "Which detail had you not noticed while making it?" },
  "122": { n: "Discover more at a second look", a: ["Look briefly at your work and note five things you notice.", "Look at it for another 30 seconds.", "Note up to five additional observations."], m: "A work of your own, paper, pen, timer", f: "What did you notice only by looking longer?" },
  "123": { n: "Describe colours, shapes and lines", a: ["Write one sentence about the colours of your work.", "Write a second sentence about the shapes and a third about the lines.", "Compare what you described with the three sentences."], m: "A work of your own, paper, pen", f: "Which sentence says the most about the work, for you?" },
  "124": { n: "First and second impression", a: ["Look briefly at your work and write down three words for your first impression.", "Then look at the work for one minute.", "Check the words: which still fit, which would you replace?"], m: "A work of your own, paper, pen, timer", f: "Which detail changed your impression, if it changed at all?" },
  "125": { n: "Find an unplanned spot", a: ["Look for a spot that turned out differently than planned.", "Look at it for a while on its own and then within the whole picture.", "Decide whether you want to keep it, change it or leave it for now."], m: "A work of your own", f: "What speaks for your decision?" },
  "126": { n: "Follow your own gaze", a: ["Look away briefly and then at your work again.", "Note the spot you look at first and the next two spots.", "Sketch the picture roughly and connect these spots in their order with arrows."], m: "A work of your own, paper, pen", f: "What attracted your gaze first?" },
  "127": { n: "Look closely and from further away", a: ["Look at the work from about a hand's width, an arm's length and a few steps away.", "For each distance note one thing that particularly strikes you.", "Compare your three observations."], m: "A work of your own, paper, pen", f: "What do you see only close up, what better from further away?" },
  "128": { n: "Look at a picture in four positions", a: ["First look at the work in its current position.", "Turn it one, two and three quarter turns in succession.", "Look at it briefly in each position without adding anything."], m: "A work of your own", f: "Which position would you choose for the work now?" },
  "129": { n: "Find a small picture in the large one", a: ["Lay the paper strips on the work as a small frame.", "Move them until you find a crop you like on its own.", "Photograph only this crop."], m: "A work of your own, 4 paper strips, smartphone", f: "What stands out more in the crop than in the whole picture?" },
  "130": { n: "Find a short title", a: ["Look at your work closely.", "Give it a title of no more than four words.", "Then look at the work again with this title in mind."], m: "A work of your own, paper, pen", f: "Does the title direct your gaze to something in particular?" },
  "131": { n: "Find three verbs", a: ["Look at your work and search for words that express a movement or a change.", "Write down three, for example grow, fall or circle.", "Point to the spots that fit your words."], m: "A work of your own, paper, pen", f: "Which word best describes what seems to be happening in the picture, for you?" },
  "132": { n: "Find five fitting words", a: ["Write down five words about the look of your work, such as dense, open, angular, soft or bright.", "Leave out judgements like «beautiful» and «ugly».", "For each word point to a matching spot in the picture."], m: "A work of your own, paper, pen", f: "Which word fits particularly many spots?" },
  "133": { n: "Look for traces of making", a: ["Imagine you had not made the work yourself.", "Look for up to five traces, such as a brushstroke, a glued edge or a fold.", "For each trace note which step of the work probably produced it."], m: "A work of your own, paper, pen", f: "Which step of the work can you recognise particularly well in the result?" },
  "134": { n: "Find three decisions again", a: ["Look for three spots where you consciously decided something, such as a colour, a cut or a distance.", "Note each decision briefly.", "Remember what you did afterwards."], m: "A work of your own, paper, pen", f: "Which decision influenced the rest of your way the most?" },
  "135": { n: "Deal with chance", a: ["Look for up to three spots that were not planned.", "Write for each spot: keep, change or still open.", "Leave the work unchanged for now."], m: "A work of your own, paper, pen", f: "Which unplanned spot do you want to keep deliberately?" },
  "136": { n: "Find your own rule again", a: ["Remember the rule, for example «only three colours».", "Look for up to three spots where you can clearly recognise the rule.", "Imagine one of these spots without the rule."], m: "A work of your own that came about with a rule", f: "What might you have done differently at this spot?" },
  "137": { n: "Find strong differences", a: ["Look for up to three spots where strong differences meet.", "Note the differences, such as light and dark, large and small or smooth and rough.", "Compare how strongly these spots catch your attention."], m: "A work of your own, paper, pen", f: "Which difference catches your eye first?" },
  "138": { n: "Follow repetitions", a: ["Look for a shape, colour or line that occurs several times.", "Draw its sequence in simplified form on a new sheet.", "Mark larger gaps or interruptions."], m: "A work of your own, paper, pen", f: "Where does the sequence change?" },
  "139": { n: "Swap shape and background", a: ["Look at a shape that strikes you at once.", "Then look at the area around it as if it were a shape itself.", "Switch between the two ways of seeing a few times."], m: "A work of your own", f: "Where does the switch succeed, where hardly at all?" },
  "140": { n: "Which colour stands out first", a: ["Look briefly at your work and note the colour you notice first.", "Then look for the next most noticeable colour. Repeat for the remaining colours.", "Compare your order with the size of the areas of colour."], m: "A coloured work of your own, paper, pen", f: "Does a small area of colour strike you more than a large one?" },
  "141": { n: "A small picture in grey", a: ["Draw a rectangle about the size of a matchbox.", "Transfer only the most important areas of your work into it.", "Use white, light grey, medium grey, dark grey and almost black. Leave out small details."], m: "A work of your own, paper, pencil", f: "Which parts of your work do you recognise in the small drawing?" },
  "142": { n: "Sum up a picture with five lines", a: ["Look at the most important directions in your work.", "On a new sheet draw no more than five lines that show these directions.", "Leave out colours and small details."], m: "A work of your own, paper, pen", f: "Which of your lines is particularly important for recognising it?" },
  "143": { n: "Compare two versions", a: ["Lay the two works side by side.", "Note three visible differences, such as in colour, size or arrangement.", "Also look for something they have in common that you did not notice at once."], m: "2 works of your own on the same task, paper, pen", f: "Which of your decisions led to one of these differences?" },
  "144": { n: "Change exactly one thing", a: ["Look at the work and choose exactly one spot you want to change.", "Decide what you want to change there, such as lengthening a line or darkening an area.", "Make only this change and put the tool down."], m: "A work of your own, a matching pen or matching paint", f: "What changes through this one intervention?" },
  "145": { n: "Think a shape away", a: ["Choose a striking shape or line.", "Imagine it were not there.", "Try this with two more spots."], m: "A work of your own", f: "Which omission would change the work the most, for you?" },
  "146": { n: "Think a shape twice", a: ["Choose a shape or line in your work.", "Imagine the same shape were there a second time.", "Try two different places for it in your mind."], m: "A work of your own", f: "In which place would the repetition change the picture the most?" },
  "147": { n: "Look for a fitting place", a: ["Try three places or heights, for example on the table, on a shelf and leaning against a wall.", "Look at the work briefly in each place.", "Choose the place where you want to leave it for now."], m: "A work of your own", f: "What about this place suits the work, for you?" },
  "148": { n: "Photograph the work", a: ["Photograph the work once as straight on as possible.", "Take two more photos from a slightly different distance or angle.", "Compare them with the original. Choose the photo that shows shapes and proportions most similarly."], m: "A work of your own, smartphone or camera", f: "What does even this photo show differently from the original?" },
  "149": { n: "Instructions for rebuilding", a: ["Describe in a few steps how someone could rebuild the arrangement of your work.", "Name shapes, colours, sizes and positions, for example «a small red circle at the top right».", "Cover the original and check whether you can imagine the picture from your instructions."], m: "A work of your own, paper, pen", f: "Which instruction would you have to make more precise?" },
  "150": { n: "Find a new beginning", a: ["Choose a detail of your work, such as a colour, line or small shape.", "Transfer this detail to a new sheet.", "Leave it as a possible beginning for a further work."], m: "A work of your own, paper, pens", f: "Starting from this detail, what would you try next?" },
  "151": { n: "Describe colours and collect ideas", a: ["For each colour write down three visible features, such as light, strong or blotchy.", "Next to it write three things it reminds you of, such as forest, holidays or a piece of clothing.", "Compare the two lists."], m: "3 coloured objects, paper, pen", f: "Which words describe the appearance, which a memory or idea?" },
  "152": { n: "Colours for a word", a: ["Choose a word, for example «loud», «cool» or «festive».", "Paint five small patches of colour that fit it for you.", "Add a sixth colour that at first does not fit."], m: "Coloured pencils, paper", f: "Can the sixth colour fit your word too? If so, how?" },
  "153": { n: "Find signs in everyday life", a: ["Look for five signs around you, such as arrow, heart, star, cross or tick.", "Draw them.", "For each note two situations in which it could occur and mean something different."], m: "Paper, pen", f: "For which sign do the meanings differ particularly strongly?" },
  "154": { n: "Choose objects by their look", a: ["Choose five objects whose shape, material or surface interests you.", "Lay them side by side.", "Order them by their appearance, for example round things together, elongated things next to them."], m: "5 small everyday objects", f: "Which two objects go together visually although they are used quite differently?" },
  "155": { n: "Describe materials by their qualities", a: ["Take each piece in your hand and feel its surface. Bend or press it carefully if possible.", "Write down two qualities for each, such as smooth, pliable, soft or springy.", "Use no material names like wood or fabric."], m: "6 pieces of material, paper, pen", f: "Which quality did you notice only by touching?" },
  "156": { n: "Observe movements", a: ["Watch five everyday movements, such as a door, a hand or a curtain.", "Write down a fitting word for each, for example slow, jerky or circling.", "Sketch one of the movements with a few lines."], m: "Paper, pen", f: "Which movement was the hardest to describe with one word?" },
  "157": { n: "An effect with another colour", a: ["Choose a quality, for example «calm» or «wild», and a colour that fits it for you.", "Draw a small picture with it that shows this quality.", "Next to it try it with a colour that hardly fits for you. Change shapes and distances to do so."], m: "Paper, coloured pencils", f: "Which shapes did you choose for the second picture?" },
  "158": { n: "One mark after another", a: ["Set a first line or blot on the sheet.", "Look briefly. Add a second mark, perhaps next to it, across it or as a continuation.", "Repeat this alternation of looking and adding ten times."], m: "Paper, pen", f: "Which mark particularly influenced your next step?" },
  "159": { n: "Continue a quick picture slowly", a: ["Paint for two minutes without a predetermined subject. Let the sheet dry.", "Choose a small area and cut it out.", "Work on slowly only on this crop, perhaps with additional lines or colour."], m: "Paper, watercolour, broad brush, water, scissors, timer", f: "What did you take over from the quick picture?" },
  "160": { n: "The same sign in three surroundings", a: ["Draw the same sign three times at the same size, for example a heart.", "Design different surroundings for each, such as flowers, a price tag or a speech bubble.", "Leave the sign itself unchanged each time."], m: "Paper, coloured pencils", f: "What could the sign mean in each of the three pictures?" },
  "161": { n: "Repeat a chance curve", a: ["Let a string fall onto the paper from a low height.", "Trace its course carefully.", "Next to it draw the same curve freehand several times, with spacing as even as possible."], m: "String, paper, pencil", f: "What looks regular through the repetition although the first line came about by chance?" },
  "162": { n: "Make a clear shape from soft fabric", a: ["Choose a shape, for example circle, triangle or square.", "Fold or roll the cloth and tie it with the string if needed.", "Put it down and try to keep the chosen shape recognisable."], m: "A small cloth, string", f: "Where does the fabric give way again?" },
  "163": { n: "Stay with the first choice", a: ["Quickly choose one colour and one tool.", "Work with those only for five minutes.", "Look at the result before you take another colour or another tool."], m: "Paper, coloured pens or paints and brush, timer", f: "What could you do with this one combination?" },
  "164": { n: "Stop after two minutes", a: ["Lay out the material and set the timer to two minutes.", "Start painting at once and decide about colours, directions and areas as you go.", "Stop at the signal and leave the picture unchanged."], m: "Paper, watercolour, broad brush, water, timer", f: "Which decision did you make particularly quickly?" },
  "165": { n: "Make a shape stand out", a: ["Spread the ten shapes on the base. Choose one that should stand out.", "Leave this shape where it is. Move the others closer to it or further away.", "Also try a coloured sheet as a new background."], m: "10 paper shapes, a sheet as a base, 2 sheets of different colours", f: "In which arrangement does your chosen shape stand out most?" },
  "166": { n: "Use a chance curve as a template", a: ["Let the string fall three times and trace its course each time.", "Trace one of the curves onto tracing paper. Hatch the back with the pencil.", "Lay the tracing paper on a new sheet. Go over the curve with some pressure so that it appears on the sheet below.", "Transfer the curve at least five times in all."], m: "String, paper, soft pencil, tracing paper", f: "From when do you recognise the recurring curve as a pattern?" },
  "167": { n: "Five kinds of lines", a: ["Write down five words: flowing, angular, swirling, light and still.", "For each word draw a matching line, such as an arc or a zigzag.", "Repeat each kind of line a few times in a small field of its own."], m: "Paper, pen", f: "In which field does the kind of line fit the word particularly well, for you?" },
  "168": { n: "A work just for you", a: ["Decide that you do not have to show this work to anyone for now.", "Draw for ten minutes with the colours and shapes you feel like.", "Look at it in between and decide each time what you want to add."], m: "Paper, coloured pencils, timer", f: "Did you try something you would otherwise rather have left out?" },
  "169": { n: "Five sheets in two minutes each", a: ["Lay out all five sheets. Work sitting or standing, whichever suits you.", "Paint on each sheet for exactly two minutes without deciding on a subject first.", "Switch to the next sheet at once after each signal. At the end lay all five side by side."], m: "5 sheets, watercolours, broad brush, water, timer", f: "Which colours, shapes or movements recur on several sheets?" },
  "170": { n: "Paint without a fixed subject", a: ["Begin with one colour and a first mark.", "Look briefly and decide what you want to add next to it, above it or after it.", "Repeat until you want to stop. No recognisable object needs to emerge."], m: "Paper, watercolours, brush, water", f: "Which spot led you to a next step?" },
  "171": { n: "Draw without explanation", a: ["Draw whatever comes to mind for ten minutes.", "Put the pens down and look at the sheet briefly.", "Leave it without a title for now and do without an explanation."], m: "Paper, pens, timer", f: "What do you notice when you just look?" },
  "172": { n: "Look, and draw rarely", a: ["Look at the object for five minutes.", "After every 30 seconds set exactly one line or mark on the sheet.", "Between the marks keep looking at the object."], m: "An object, paper, pen, timer", f: "Which detail did you discover while waiting?" },
  "173": { n: "Draw movements", a: ["Move your hand or arm in turn softly, angularly, chaotically, lightly and very slowly.", "After each movement draw lines on a new sheet for one minute that fit it.", "Lay the five drawings side by side."], m: "Some space, 5 sheets, pen, timer", f: "Which drawing reminds you most clearly of your movement?" },
  "174": { n: "Draw a process", a: ["Choose a simple process, for example making tea.", "Draw it for five minutes with words, circles and arrows. Connect what belongs together or follows on.", "Look at the drawing and add a missing step if you notice one."], m: "Large paper, pen, timer", f: "While drawing, did you notice a step you had not thought of before?" },
  "175": { n: "Distinguish observation and interpretation", a: ["Write six short sentences about your work.", "Mark what is directly visible, such as «The line is jagged», and what you interpret, such as «The line looks angry».", "Split sentences that contain both into two separate statements."], m: "A work of your own, paper, pen", f: "Which statement was the hardest to assign?" },
  "176": { n: "Look at colour and arrangement", a: ["Choose two striking colours of your work. Note one impression for each, such as calm or loud.", "Look more closely: how large, how light and where are the areas of colour?", "Note what apart from the colour could contribute to your impression."], m: "A coloured work of your own, paper, pen", f: "What role could the arrangement play in your impression?" },
  "177": { n: "Allow several meanings", a: ["Choose a striking sign or shape in your work.", "Write down three different things that could be seen in it.", "Look at the shape in turn with each of these three ideas in mind."], m: "A work of your own, paper, pen", f: "With which idea do you perceive the shape differently?" },
  "178": { n: "Direct your gaze to another shape", a: ["Choose the shape you notice first and look at it for two minutes.", "Then deliberately direct your gaze to another shape.", "Now look at the remaining parts as its surroundings."], m: "A work of your own, timer", f: "What do you perceive differently at the second look?" },
  "179": { n: "Three minutes in front of your own picture", a: ["Set the timer to three minutes and look at your work.", "Leave it unchanged during this time. Do not photograph or describe it yet.", "Afterwards note up to three things you noticed anew."], m: "A work of your own, paper, pen, timer", f: "Which observation only came after a while?" },
  "180": { n: "Distinguish chance and decision", a: ["Choose five striking spots in your work.", "For each note: came about rather by chance, rather deliberately designed, or both.", "Think about whether you later deliberately left a chance mark as it was."], m: "A work of your own, paper, pen", f: "At which spot did chance and decision come together?" },
};
